        "_index": "testindex1",
        "_id": "2",
        "_score": 1,
        "_source": {
          "name": "Economy brand",
          "product_to_brand": "brand"
        }
      }
    ]
  }
}
```

## Retrieving inner hits

To return child documents that matched the query, provide the `inner_hits` parameter:

```json
