    "total": 1,
    "successful": 1,
    "skipped": 0,
    "failed": 0
  },
  "hits": {
    "total": {
      "value": 4,
      "relation": "eq"
    },
    "max_score": null,
    "hits": [
      {
        "_index": "scripting-products",
        "_id": "3",
        "_score": null,
        "_source": {
          "name": "Mechanical keyboard"
        },
        "fields": {
          "average_rating": [
            5.0
          ]
        },
        "sort": [
          "ACC-2001"
        ]
      },
      {
        "_index": "scripting-products",
        "_id": "1",
        "_score": null,
        "_source": {
          "name": "Wireless noise cancelling headphones"
        },
        "fields": {
          "average_rating": [
            4.25
          ]
        },
        "sort": [
          "AUD-1001"
        ]
      },
      {
        "_index": "scripting-products",
        "_id": "2",
        "_score": null,
        "_source": {
          "name": "Wireless earbuds"
        },
